const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define New York region (bounding box)
  const nyGeometry = ee.Geometry.Rectangle([-79.5, 40.5, -71.5, 45.0]);

  // ERA5 daily air temperature
  const era5Daily = ee.ImageCollection('ECMWF/COPERNICUS/ERA5/DAILY');

  // Filter for Jan 29, 2019
  const jan29 = era5Daily
    .filterDate('2019-01-29', '2019-01-30')
    .filterBounds(nyGeometry)
    .select('temperature_2m');

  // Filter for Feb 5, 2019
  const feb5 = era5Daily
    .filterDate('2019-02-05', '2019-02-06')
    .filterBounds(nyGeometry)
    .select('temperature_2m');

  const size29 = jan29.size().getInfo();
  const size5 = feb5.size().getInfo();

  console.log(`Jan 29 Images: ${size29}, Feb 5 Images: ${size5}`);

  // Check if data exists
  if (size29 === 0 || size5 === 0) {
    console.log("No data available for one or both dates.");
    console.log("C1");
    return;
  }

  // Get mean temperature for each date (convert from Kelvin to Celsius)
  const temp29Img = jan29.mean();
  const temp5Img = feb5.mean();

  const temp29K = temp29Img.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: nyGeometry,
    scale: 10000,
    maxPixels: 1e9
  }).get('temperature_2m').getInfo();

  const temp5K = temp5Img.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: nyGeometry,
    scale: 10000,
    maxPixels: 1e9
  }).get('temperature_2m').getInfo();

  // Convert from Kelvin to Celsius
  const temp29C = temp29K - 273.15;
  const temp5C = temp5K - 273.15;

  console.log(`Jan 29 Temp: ${temp29C.toFixed(2)}°C, Feb 5 Temp: ${temp5C.toFixed(2)}°C`);

  // Validate results
  if (temp29C === null || temp5C === null || isNaN(temp29C) || isNaN(temp5C)) {
    console.log("Calculation resulted in null or NaN.");
    console.log("C3");
    return;
  }

  // Check if temperatures are within reasonable range for NY
  if (temp29C < -50 || temp29C > 50 || temp5C < -50 || temp5C > 50) {
    console.log("Temperature out of reasonable range for New York.");
    console.log("C3");
    return;
  }

  // Calculate absolute difference
  const tempDiff = Math.abs(temp29C - temp5C);
  console.log(`Temperature Difference: ${tempDiff.toFixed(2)}°C`);

  // Check if difference >= 24°C
  if (tempDiff >= 24.0) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
